package com.example

import com.example.ExamQuestionHelper.QSpec

object HealthLiveExamPersonalHealthBank2 {
    private const val T = "පෞද්ගලික සෞඛ්‍යය, ඉරියව් හා ශරීර සංවර්ධනය"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("පුද්ගලයෙකුගේ සිරුරේ බර 60 kg සහ උස 1.5 m (මීටර් 1.50) නම් ඔහුගේ BMI අගය කොපමණද?", "26.7 kg/m² (වැඩි බර)", "20.0 kg/m² (නිරෝගී)", "15.5 kg/m² (අඩු බර)", "35.0 kg/m² (ස්ථූල)", "BMI = 60 / (1.5 × 1.5) = 60 / 2.25 = 26.67 kg/m² වේ."),
        q("පුද්ගලයෙකුගේ සිරුරේ බර 50 kg සහ උස 2.0 m නම් ඔහුගේ ශරීර ස්කන්ධ දර්ශකය (BMI) කුමක්ද?", "12.5 kg/m² (අඩු බර)", "25.0 kg/m² (වැඩි බර)", "20.0 kg/m² (නිරෝගී)", "30.0 kg/m² (ස්ථූල)", "BMI = 50 / (2.0 × 2.0) = 50 / 4 = 12.5 kg/m² වේ."),
        q("පුද්ගලයෙකුගේ සිරුරේ බර 72 kg සහ උස 1.6 m (මීටර් 1.60) නම් ඔහුගේ BMI අගය කුමක්ද?", "28.1 kg/m² (වැඩි බර)", "22.5 kg/m² (නිරෝගී)", "18.0 kg/m² (අඩු බර)", "32.0 kg/m² (ස්ථූල)", "BMI = 72 / (1.6 × 1.6) = 72 / 2.56 = 28.125 kg/m² වේ."),
        q("බර 45 kg සහ උස 1.5 m වූ පාසල් දැරියකගේ BMI අගය සහ ඇය අයත් වන කාණ්ඩය කුමක්ද?", "20.0 kg/m² (නිරෝගී බර)", "15.0 kg/m² (අඩු බර)", "25.0 kg/m² (වැඩි බර)", "30.0 kg/m² (ස්ථූල)", "BMI = 45 / (1.5 × 1.5) = 45 / 2.25 = 20.0 kg/m² (නිරෝගී බර)."),
        q("බර 80 kg සහ උස 1.6 m වූ අයෙකුගේ BMI අගය අනුව ඔහු අයත් වන්නේ කුමන කාණ්ඩයටද?", "31.25 kg/m² (ස්ථූලතාව)", "24.0 kg/m² (නිරෝගී)", "19.5 kg/m² (අඩු බර)", "17.0 kg/m² (දරුණු අඩු බර)", "BMI = 80 / (1.6 × 1.6) = 80 / 2.56 = 31.25 kg/m² (ස්ථූලතාව)."),
        q("බර 40 kg සහ උස 1.6 m වූ යෞවනයෙකුගේ BMI අගය අනුව ඔහු අයත් වන කාණ්ඩය කුමක්ද?", "15.6 kg/m² (අඩු බර)", "22.0 kg/m² (නිරෝගී)", "26.5 kg/m² (වැඩි බර)", "31.0 kg/m² (ස්ථූල)", "BMI = 40 / 2.56 = 15.625 kg/m² වන බැවින් අඩු බර කාණ්ඩයට අයත් වේ."),
        q("බර 54 kg සහ උස 1.5 m වූ ශිෂ්‍යයෙකුගේ BMI අගය නිවැරදිව ගණනය කළ විට ලැබෙන්නේ කුමක්ද?", "24.0 kg/m² (නිරෝගී බර)", "18.0 kg/m² (අඩු බර)", "28.0 kg/m² (වැඩි බර)", "32.0 kg/m² (ස්ථූල)", "BMI = 54 / 2.25 = 24.0 kg/m² (නිරෝගී බර)."),
        q("පාසල් ශිෂ්‍යයෙකුගේ පෞද්ගලික සනීපාරක්ෂාව පිරිහී යාමෙන් ඇතිවිය හැකි සෘජු ප්‍රතිඵලයක් කුමක්ද?", "බෝවන රෝගවලට නිරාවරණය වීම හා ආත්ම විශ්වාසය අඩුවීම", "ශරීරයේ උස අනවශ්‍ය ලෙස වැඩිවීම", "බුද්ධි මට්ටම ඉහළ යාම", "අක්ෂි පෙනීම තියුණු වීම", "අපිරිසිදුකම නිසා විෂබීජ ආසාදන පහසුවෙන් ශරීරගත වේ."),
        q("ඇවිදීමේදී අනුගමනය කළ යුතු වඩාත් නිවැරදි හා කාර්යක්ෂම ඉරියව්ව කුමක්ද?", "හිස කෙළින් තබා උරහිස් ලිහිල්ව සමබරව තබාගෙන විලුඹ පළමුව බිම තැබීම", "බිම දෙස පමණක් බලාගෙන පාදය ඇදගෙන යාම", "අත් සාක්කුවල දමාගෙන ඉදිරියට නැමී ඇවිදීම", "ඇඟිලි තුඩුවලින් පමණක් ඇවිදීම", "ඇවිදීමේදී විලුඹෙන් පටන් ගෙන අඩි පතුල හරහා ඇඟිලි දක්වා බර මාරු විය යුතුය."),
        q("දීර්ඝ වේලාවක් එක දිගට සිටගෙන සිටීමට සිදුවන අවස්ථාවක කොන්දේ විඩාව අවම කර ගැනීමට කළ හැකි සුදුසුම ක්‍රියාව කුමක්ද?", "වරින් වර එක් පාදයක් මත කුඩා ලෑල්ලක් හෝ මිටි ආධාරකයක් තබා බර මාරු කිරීම", "දණහිස් තදින් අගුළු ලාගෙන එකම ඉරියව්වක සිටීම", "පසුපසට අධික ලෙස නැමී සිටීම", "ඉදිරියට නෙරා සිටීම", "පාද මාරු කරමින් බර වෙනස් කිරීමෙන් කටී කශේරුකාවල පීඩනය ලිහිල් වේ."),
        q("පාවහන් තෝරාගැනීමේදී පාදයේ නිරෝගීභාවය සඳහා වඩාත් සැලකිලිමත් විය යුතු සාධකය කුමක්ද?", "පාදයට නිසි ඉඩ ඇති, පතුලේ චාපයට හොඳ ආධාරකයක් සපයන මිටි අඩි සහිත වීම", "ඉතා උස් අඩි සහිත හා ඇඟිලි තද වන පටු පාවහන්", "ප්‍රමාණයට වඩා ඉතා විශාල පාවහන්", "පතුල ඉතා ලිස්සන සුළු පාවහන්", "උස් අඩි සහිත සපත්තු නිසා කොන්දේ ලෝඩෝසිස් ඉරියව් දෝෂය හටගනී."),
        q("නිතර අධික උස අඩි සහිත පාවහන් (High heels) පැළඳීම නිසා හටගත හැකි කායික ඉරියව් ආබාධය කුමක්ද?", "තුනටිය ඉදිරියට නැමී ලෝඩෝසිස් තත්ත්වය හටගැනීම", "කයිෆෝසිස්", "පැතලි පාදය", "ස්කොලියෝසිස්", "උස් අඩි පාවහන් ශරීරයේ ගුරුත්ව කේන්ද්‍රය ඉදිරියට යොමු කර තුනටියට අධික වෙහෙසක් ගෙනදේ."),
        q("පැතලි පාදය (Flat foot) ආබාධය සහිත පුද්ගලයෙකුට පාදයේ ආරුක්කුව සකස් කර ගැනීමට නිර්දේශ කරන සරල ව්‍යායාමයක් කුමක්ද?", "පාදයේ ඇඟිලිවලින් බිම ඇති කිරිගරුඬ බෝල හෝ රෙදි කැබලි එසවීම", "බරින් වැඩි බෑග් එසවීම", "උසින් පැනීම", "දිගු වේලාවක් නිශ්චලව සිටීම", "පාදයේ ඇඟිලි නමමින් යටිපතුලේ කුඩා මාංශපේශී ශක්තිමත් කළ හැකිය."),
        q("ශිෂ්‍යයෙකු නිවැරදි ලිවීමේ ඉරියව්ව පවත්වා ගැනීමට මේසය හා පුටුව අතර තිබිය යුතු නිවැරදි සබඳතාව කුමක්ද?", "වැලමිට මේස මට්ටමේ පිහිටන සේ පුටුවේ උස ගැළපීම", "මේසය පපුවට වඩා උසින් තිබීම", "පුටුව ඉතා පහත් වී මේසය උස්වීම", "පාද බිම නොගෑවෙන සේ පුටුව උස්වීම", "මේසයේ හා පුටුවේ උස ශිෂ්‍යයාගේ උසට ගැළපීම ඉරියව් දෝෂ වළක්වයි."),
        q("කොඳු ඇට පෙළේ ස්වාභාවික වක්‍රතා නිසි පරිදි පිහිටා තිබීමෙන් ශරීරයට සැලසෙන ප්‍රධාන යාන්ත්‍රික වාසිය කුමක්ද?", "ඇවිදීමේදී හා පැනීමේදී ඇතිවන කම්පන අවශෝෂණය කර ගැනීම (Shock absorption)", "ශරීරය දැඩි ලීයක් මෙන් ඝනකම් වීම", "සන්ධි චලනය සම්පූර්ණයෙන් නැවැත්වීම", "රුධිර පීඩනය ඉහළ දැමීම", "ස්වාභාවික 'S' හැඩැති වක්‍රතාව කම්පන අවශෝෂකයක් (Spring) ලෙස ක්‍රියා කරයි."),
        q("දත්වල මතුපිට ආරක්ෂා කරන මිනිස් සිරුරේ ඇති දෘඪතම හා ඛනිජ බහුලතම පටකය කුමක්ද?", "එනමලය (Enamel)", "දන්ත ඇටය (Dentine)", "දන්ත මජ්ජාව (Pulp)", "විදුරුමස", "දතෙහි බාහිරින්ම පිහිටි එනමලය කැල්සියම් හා පොස්පරස්වලින් සමන්විත දෘඪ ආවරණයකි."),
        q("දතෙහි රුධිර වාහිනී හා ස්නායු පිහිටා ඇති ජීවී මධ්‍යම කොටස හඳුන්වන්නේ කුමන නමින්ද?", "දන්ත මජ්ජා කුහරය (Pulp cavity)", "එනමලය", "දන්ත ඇටය", "සිමෙන්ටම්", "දන්ත කුහරය ගැඹුරට ගොස් මජ්ජාවට ළඟා වූ විට දැඩි දත් කැක්කුමක් හටගනී."),
        q("රාත්‍රී නින්දට පෙර දත් මැදීම විශේෂයෙන්ම අත්‍යවශ්‍ය වීමට හේතුව කුමක්ද?", "නින්දේදී කෙළ ශ්‍රාවය අඩුවන බැවින් මුඛයේ බැක්ටීරියා ක්‍රියාකාරිත්වය වේගවත් වන නිසා", "දත්වල වර්ණය වෙනස් නොවන නිසා", "නින්දේදී කෙළ වැඩිපුර ශ්‍රාවය වන නිසා", "හිසරදය වළක්වා ගැනීමට", "නින්දේදී කෙළ මගින් මුඛය ස්වභාවිකව සේදීම අවම බැවින් බැක්ටීරියා පහසුවෙන් අම්ල නිපදවයි."),
        q("නියපොතු නිතර දත්වලින් සැපීම (Nail biting) නිසා ඇතිවිය හැකි සෞඛ්‍ය ගැටලුවක් කුමක්ද?", "නියපොතු යට ඇති විෂබීජ හා පණුවන් මුඛය හරහා ආන්ත්‍රගත වීම", "නියපොතු අධික ලෙස දික්වීම", "ඇස් පෙනීම දුර්වල වීම", "කන් ඇසීම අඩු වීම", "නිය යට රැඳෙන බැක්ටීරියා හා පණු බිත්තර නිය සැපීමෙන් ශරීරගත වේ."),
        q("ඇස්වල කෝනියාවේ හෝ කාචයේ වක්‍රතාවේ විෂමතා නිසා රූප පැහැදිලිව නොපෙනී යාමේ දෘෂ්ටි දෝෂය කුමක්ද?", "ඇස්ටිග්මැටිසම් (Astigmatism)", "දුර දෘෂ්ටිකතාව", "අවිදුර දෘෂ්ටිකතාව", "සුද ඒම", "Astigmatism තත්ත්වයේදී ආලෝක කිරණ එකම ලක්ෂ්‍යයකට නාභිගත නොවේ."),
        q("අක්ෂි ආසාදනයක් වන 'ඇස් ලෙඩ' (Conjunctivitis) රෝගය පැතිරීම පාලනය කිරීමට ගත යුතු පියවරක් කුමක්ද?", "ආසාදිතයාගේ ලේන්සු, තුවා හෝ කොට්ට උර හවුලේ භාවිත නොකිරීම", "ඇස් නිතර අත්වලින් පොඩි කිරීම", "අනෙක් අයගේ ඇස් කණ්ණාඩි පැළඳීම", "පොදු පිහිනුම් තටාකවල නෑම", "Conjunctivitis වෛරස් හෝ බැක්ටීරියා මගින් ස්පර්ශය හරහා කඩිනමින් බෝවේ."),
        q("ශ්‍රවණාබාධ ඇතිවීම වැළැක්වීම සඳහා හෙඩ්ෆෝන් හෝ ඉයර්ෆෝන් භාවිතයේදී අනුගමනය කළ යුතු සෞඛ්‍ය උපදෙස කුමක්ද?", "උපරිම ශබ්ද මට්ටමෙන් 60% ට වඩා අඩුවෙන් හා පැයකට වඩා අඛණ්ඩව භාවිත නොකිරීම", "උපරිම ශබ්දයෙන් පැය 6ක් ඇසීම", "නිදාගන්නා තුරුම හෙඩ්ෆෝන් දමාගෙන සිටීම", "එක් කනකට පමණක් අධික ශබ්දය දැමීම", "අධික ශබ්දයට නිරාවරණය වීමෙන් කර්ණශංඛයේ සියුම් රෝම සෛල විනාශ වී ස්ථිර බිහිරි බව ඇතිවේ."),
        q("ශාරීරික ඉරියව් නිවැරදිව පවත්වා ගැනීමට දායක වන මූලික මාංශපේශී කාණ්ඩය (Core muscles) පිහිටා ඇත්තේ කොහේද?", "උදරය, කොන්ද හා ශ්‍රෝණි කලාපයේ", "අත්ලෙහි හා ඇඟිලිවල", "පාදයේ ඇඟිලි තුඩුවල", "කන් පෙතිවල", "ශරීර මධ්‍යයේ Core මාංශපේශී ශක්තිමත් වීමෙන් කොඳු ඇට පෙළේ සමබරතාව රැකේ."),
        q("පාසල් බෑගයක බර ශිෂ්‍යයාගේ ශරීර බරින් කොපමණ ප්‍රතිශතයක් නොඉක්මවිය යුතුද?", "10% සිට 15% දක්වා නොඉක්මවිය යුතුය", "50% ඉක්මවිය යුතුය", "40% ක් විය යුතුය", "ශරීර බරට සමාන විය යුතුය", "ශරීර බරින් 10% ට වඩා බෑගයේ බර වැඩි වූ විට කොඳු ඇට පෙළට හානි සිදුවේ."),
        q("ශිෂ්‍ය සෞඛ්‍ය ප්‍රවර්ධන වැඩසටහන යටතේ පාසල තුළ මූලිකවම සුරක්ෂිත කළ යුතු සනීපාරක්ෂක අංගයක් කුමක්ද?", "පිරිසිදු පානීය ජලය හා සබන් සහිත පිරිසිදු වැසිකිළි පහසුකම්", "රූපවාහිනී නැරඹුම් මැදිරි", "විසිතුරු පැළෑටි පමණක්", "මිල අධික ක්‍රීඩා ඇඳුම්", "පානීය ජලය හා සනීපාරක්ෂාව පාසල් දරුවන්ගේ නිරෝගීභාවයට මූලිකම අවශ්‍යතාවකි."),
        q("පාසල් ආපනශාලාවල විකිණීම සඳහා සම්පූර්ණයෙන්ම තහනම් කර ඇති ආහාර කාණ්ඩයක් වන්නේ කුමක්ද?", "කෘත්‍රිම රසකාරක, වර්ණක හා අධික සීනි/ලුණු අඩංගු පැණිබීම හා පැකට් කළ කෙටි කෑම", "ධාන්‍ය තම්බා සාදන ලද ආහාර", "නැවුම් පළතුරු යුෂ", "එළවළු රොටී", "චක්‍රලේඛ මගින් පාසල් ආපනශාලාවල කාබනේටඩ් බීම හා කෘත්‍රිම කෑම තහනම් කර ඇත."),
        q("ළමා හා නව යොවුන් වියේදී ප්‍රමාණවත් ලෙස ජලය පානය නොකිරීමෙන් (Dehydration) ඇතිවිය හැකි සෘජු ආබාධයක් කුමක්ද?", "තෙහෙට්ටුව, හිසරදය, මලබද්ධය හා අවධානය හීන වීම", "අස්ථි බිඳීම", "දත් නෙරා ඒම", "හිසකෙස් සුදුවීම", "දිනකට සිරුරට අවශ්‍ය ප්‍රශස්ථ ජල ප්‍රමාණය (වතුර වීදුරු 6-8) ලබාගත යුතුය."),
        q("ශරීරයේ දහඩිය දැමීම මගින් ඉටුවන ප්‍රධානතම කායික විද්‍යාත්මක ධර්මය කුමක්ද?", "ශරීරයේ උෂ්ණත්වය නියාමනය කිරීම (ශරීරය සිසිල් කිරීම)", "ශරීරයේ රුධිරය පිටතට යැවීම", "ආහාර දිරවීම වේගවත් කිරීම", "අස්ථි ශක්තිමත් කිරීම", "දහඩිය වාෂ්පීකරණය වීම මගින් අභ්‍යන්තර ශරීර උෂ්ණත්වය 37°C ආසන්නයේ ස්ථාවරව තබා ගනී."),
        q("අව්වේ වැඩ කිරීමේදී හෝ දැඩි ක්‍රීඩා පුහුණුවකදී අධික ලෙස ජලය හා ලවණ පිටවීමෙන් ඇතිවන 'තාප මූර්ඡාව' (Heat Exhaustion) වළක්වා ගැනීමට ගත යුතු පියවර කුමක්ද?", "ජලය හා ජීවනී වැනි ඉලෙක්ට්‍රොලයිට් ද්‍රාවණ වරින් වර පානය කිරීම", "ආහාර නොගෙන සිටීම", "ඝන ඇඳුම් කිහිපයක් ඇඳීම", "ජලය කිසිසේත්ම නොබීම", "දහඩිය සමග පිටවන ලවණ ප්‍රතිපූර්ණය කිරීමෙන් විජලනය හා ක්ලාන්තය වළකී."),
        q("සිරුරේ බර 48 kg සහ උස 1.6 m වූ අයෙකුගේ BMI අගය ගණනය කළ විට ලැබෙන අගය කුමක්ද?", "18.75 kg/m² (නිරෝගී බර)", "25.5 kg/m² (වැඩි බර)", "14.2 kg/m² (අඩු බර)", "30.0 kg/m² (ස්ථූල)", "BMI = 48 / (1.6 × 1.6) = 48 / 2.56 = 18.75 kg/m² (නිරෝගී බර)."),
        q("පුද්ගලයෙකුගේ උදරීය වටප්‍රමාණය (Waist circumference) පිරිමින්ගේ 90 cm සහ කාන්තාවන්ගේ 80 cm ඉක්මවීම කුමන අවදානමක් පෙන්වයිද?", "හෘද රෝග හා දෙවන වර්ගයේ දියවැඩියාව ඇතිවීමේ ඉහළ අවදානම", "පෙනහළු පිළිකා අවදානම", "අක්ෂි ආබාධ", "ශ්‍රවණාබාධ", "උදරීය මේදය (Visceral fat) ඉහළ යාම පරිවෘත්තීය සින්ඩ්‍රෝමය හා බෝ නොවන රෝගවලට මුල් වේ."),
        q("ශාරීරික ඉරියව් ආබාධ හඳුනාගැනීම සඳහා පාසල් වෛද්‍ය පරීක්ෂණයේදී යොදාගන්නා පරීක්ෂණයක් වන්නේ කුමක්ද?", "ඇඩම්ස් ඉදිරියට නැමීමේ පරීක්ෂණය (Adams Forward Bend Test)", "බ්ලීප් පරීක්ෂණය", "ශ්‍රවණ පරීක්ෂණය", "අක්ෂි පරීක්ෂණය", "Adams Forward Bend Test මගින් කොඳු ඇට පෙළේ ස්කොලියෝසිස් ඇදවීම් පහසුවෙන් නිරීක්ෂණය කළ හැක."),
        q("යෞවන වියේදී දිනපතා ක්‍රියාශීලී ව්‍යායාමවල යෙදීමෙන් අස්ථි පද්ධතියට ලැබෙන ප්‍රධානතම වාසිය කුමක්ද?", "උපරිම අස්ථි ස්කන්ධය (Peak Bone Mass) වර්ධනය වී අනාගතයේදී ඔස්ටියෝපොරෝසිස් වැළකීම", "අස්ථි ගණන අඩුවීම", "සන්ධි සෙලවීම නැවතීම", "අස්ථි මෘදු වීම", "බර දරන ව්‍යායාම මගින් අස්ථිවල කැල්සියම් තැන්පත්වීම උත්තේජනය වේ."),
        q("ඉරියව් ආබාධයක් වන කයිෆෝසිස් (Kyphosis) සමනය කර ගැනීමට උපකාරී වන ව්‍යායාම වර්ගය කුමක්ද?", "පපුවේ පේශි ඇදීම (Chest stretch) සහ ඉහළ පිටුපස පේශි ශක්තිමත් කිරීම", "ඉදිරියට නැමී බර එසවීම", "හිස පහත් කර සිටීම", "බඩේ පේශි තද කිරීම", "පපුවේ පෙක්ටොරල් පේශි ලිහිල් කර පිටුපස රොම්බොයිඩ් පේශි ශක්තිමත් කිරීමෙන් උරහිස් පසුපසට ඇදේ."),
        q("සම මතුපිට පිහිටි 'ස්නේහස්‍රාවී ග්‍රන්ථි' (Sebaceous glands) අධික ලෙස තෙල් ශ්‍රාවය කිරීම හා බැක්ටීරියා එක්වීමෙන් මුහුණේ ඇතිවන තත්ත්වය කුමක්ද?", "කුරුලෑ (Acne vulgaris)", "අළුහම්", "හොරි", "දද", "නව යොවුන් වියේ හෝමෝන උච්චාවචනයත් සමග කුරුලෑ හටගැනීම සුලබය."),
        q("කුරුලෑ ඇතිවීම පාලනය කර ගැනීමට අනුගමනය කළ යුතු නිවැරදි සනීපාරක්ෂක පිළිවෙත කුමක්ද?", "මුහුණ මෘදු සබන් යොදා දිනකට දෙවරක් සේදීම හා කුරුලෑ මිරිකීමෙන් වැළකීම", "කුරුලෑ නියපොතුවලින් කැඩීම", "තෙල් සහිත ක්‍රීම් වර්ග අධිකව ආලේප කිරීම", "මුහුණ කිසිසේත්ම නොසේදීම", "කුරුලෑ මිරිකීමෙන් කැළැල් හා දරුණු ද්විතීයික බැක්ටීරියා ආසාදන හටගනී."),
        q("අඩු බර සහිත (BMI < 18.5) පාසල් සිසුවෙකු නිරෝගී බර මට්ටමට ළඟාවීම සඳහා කළ යුත්තේ කුමක්ද?", "ප්‍රෝටීන හා කැලරි බහුල පෝෂ්‍යදායී ආහාර වේල් ප්‍රමාණය වැඩි කිරීම හා පේශි වර්ධන ව්‍යායාම", "ක්ෂණික කෘත්‍රිම කෑම අධිකව ගැනීම", "ව්‍යායාම සම්පූර්ණයෙන්ම නැවැත්වීම", "දිවා රෑ නිදාගැනීම පමණක්", "සෞඛ්‍ය සම්පන්න කාබෝහයිඩ්‍රේට, ප්‍රෝටීන හා සමබර ආහාර මගින් ශරීර බර ක්‍රමිකව වැඩි කරගත යුතුය."),
        q("වැඩි බර හෝ ස්ථූල (BMI ≥ 25) පුද්ගලයෙකු තම බර පාලනය කර ගැනීම සඳහා ගත යුතු නිවැරදි පියවර කුමක්ද?", "සීනි හා තෙල් සහිත ආහාර සීමා කිරීම, එළවළු/පළතුරු වැඩි කිරීම හා දිනපතා ක්‍රියාශීලී ව්‍යායාම", "ආහාර සම්පූර්ණයෙන්ම වර්ජනය කිරීම", "ඖෂධ පෙති බී ආහාර නොගෙන සිටීම", "පැණිබීම පමණක් පානය කිරීම", "සමබල ආහාර පාලනය හා දිනපතා ශක්තිය වැයවන ව්‍යායාම මගින් සෞඛ්‍යාරක්ෂිතව බර අඩු කරගත හැක."),
        q("මිනිස් සිරුරේ බරින් දළ වශයෙන් කොපමණ ප්‍රතිශතයක් ජලයෙන් සමන්විත වේද?", "60% සිට 70% දක්වා", "20% සිට 30% දක්වා", "90% සිට 95% දක්වා", "10% සිට 15% දක්වා", "වැඩිහිටි මිනිස් සිරුරේ බරින් 60% කට වඩා අඩංගු වන්නේ ජලයයි."),
        q("දිනපතා උදෑසන ආහාරය (Breakfast) ගැනීම පාසල් සිසුවෙකුගේ අධ්‍යාපනික කාර්යසාධනයට වැදගත් වන්නේ ඇයි?", "රාත්‍රී උපවාසයෙන් පසු මොළයට අවශ්‍ය ග්ලූකෝස් සපයා අවධානය හා මතක ශක්තිය රඳවා ගැනීමට", "ශරීරයේ උස ක්ෂණිකව වැඩි කිරීමට", "දිවා ආහාරය ගැනීම සම්පූර්ණයෙන් නැවැත්වීමට", "දත් ශක්තිමත් කිරීමට", "උදෑසන ආහාරය මගහැරීමෙන් ක්ලාන්තය, අලසබව හා ඉගෙනුම් දුර්වලතා ඇතිවේ."),
        q("පාසල් පරිශ්‍රය තුළ හඳුනාගන්නා සෞඛ්‍ය හා ඉරියව් ගැටලු සහිත සිසුන් යොමු කරනු ලබන්නේ කුමන සායනය වෙතද?", "පාසල් දන්ත සායනය හා ප්‍රාදේශීය සෞඛ්‍ය වෛද්‍ය නිලධාරී (MOH) කාර්යාලය වෙත", "පොලිස් ස්ථානය වෙත", "ප්‍රාදේශීය ලේකම් වෙත", "සමථ මණ්ඩලය වෙත", "MOH කාර්යාලය හා පාසල් දන්ත සායන මගින් සිසුන්ට නොමිලේ ප්‍රතිකාර හා උපදෙස් ලබාදේ."),
        q("ක්‍රීඩාවකදී හෝ දෛනික කාර්යයකදී නිවැරදි ශරීර යාන්ත්‍ර විද්‍යාව (Body Mechanics) භාවිත කිරීමේ මූලික වාසිය කුමක්ද?", "අවම ශක්තියකින් උපරිම කාර්යක්ෂමතාව ලබාගැනීම හා මාංශපේශී ආබාධ වැළකීම", "ශරීරය ඉක්මනින් විඩාවට පත්වීම", "අස්ථි බිඳී යාම", "අධික ලෙස හුස්ම ගැනීම", "නිවැරදි ඉරියව් හා චලන ක්‍රම මගින් ශරීරයට සිදුවන අනවශ්‍ය වෙහෙස හා අනතුරු වළක්වයි."),
        q("සිරුරේ බර 65 kg සහ උස 1.6 m වූ කාන්තාවකගේ BMI අගය නිවැරදිව ගණනය කළ විට ලැබෙන්නේ කුමක්ද?", "25.39 kg/m² (වැඩි බර)", "19.5 kg/m² (නිරෝගී)", "16.0 kg/m² (අඩු බර)", "31.0 kg/m² (ස්ථූල)", "BMI = 65 / (1.6 × 1.6) = 65 / 2.56 = 25.39 kg/m² (වැඩි බර කාණ්ඩය)."),
        q("සිරුරේ බර 58 kg සහ උස 1.7 m වූ පුද්ගලයෙකුගේ BMI අගය නිවැරදිව ගණනය කළ විට ලැබෙන්නේ කුමක්ද?", "20.07 kg/m² (නිරෝගී බර)", "15.5 kg/m² (අඩු බර)", "27.0 kg/m² (වැඩි බර)", "32.0 kg/m² (ස්ථූල)", "BMI = 58 / (1.7 × 1.7) = 58 / 2.89 = 20.07 kg/m² (නිරෝගී බර)."),
        q("සිරුරේ බර 85 kg සහ උස 1.7 m වූ පුද්ගලයෙකුගේ BMI අගය හා ශරීර තත්ත්වය කුමක්ද?", "29.41 kg/m² (වැඩි බර)", "22.0 kg/m² (නිරෝගී)", "17.5 kg/m² (අඩු බර)", "36.0 kg/m² (දරුණු ස්ථූල)", "BMI = 85 / (1.7 × 1.7) = 85 / 2.89 = 29.41 kg/m² (වැඩි බර කාණ්ඩය)."),
        q("සිරුරේ බර 90 kg සහ උස 1.7 m වූ පුද්ගලයෙකුගේ BMI අගය අනුව ඔහු අයත් වන්නේ කුමන කාණ්ඩයටද?", "31.14 kg/m² (ස්ථූලතාව)", "24.5 kg/m² (නිරෝගී)", "18.0 kg/m² (අඩු බර)", "26.0 kg/m² (වැඩි බර)", "BMI = 90 / 2.89 = 31.14 kg/m² වන බැවින් ස්ථූලතා කාණ්ඩයට අයත් වේ."),
        q("සිරුරේ බර 42 kg සහ උස 1.5 m වූ ශිෂ්‍යාවකගේ BMI අගය ගණනය කළ විට ලැබෙන්නේ කුමක්ද?", "18.67 kg/m² (නිරෝගී බර)", "14.5 kg/m² (අඩු බර)", "25.0 kg/m² (වැඩි බර)", "30.0 kg/m² (ස්ථූල)", "BMI = 42 / (1.5 × 1.5) = 42 / 2.25 = 18.67 kg/m² (නිරෝගී බර)."),
        q("සිරුරේ බර 38 kg සහ උස 1.5 m වූ ශිෂ්‍යයෙකුගේ BMI අගය අනුව ඔහුගේ සෞඛ්‍ය තත්ත්වය කුමක්ද?", "16.89 kg/m² (අඩු බර තත්ත්වය)", "22.5 kg/m² (නිරෝගී බර)", "26.0 kg/m² (වැඩි බර)", "30.5 kg/m² (ස්ථූල)", "BMI = 38 / 2.25 = 16.89 kg/m² බැවින් 18.5 ට අඩු අඩු බර තත්ත්වයකි."),
        q("සිරුරේ බර 70 kg සහ උස 1.75 m වූ ක්‍රීඩකයෙකුගේ BMI අගය නිවැරදිව ගණනය කළ විට ලැබෙන්නේ කුමක්ද?", "22.86 kg/m² (නිරෝගී බර)", "28.5 kg/m² (වැඩි බර)", "17.0 kg/m² (අඩු බර)", "33.0 kg/m² (ස්ථූල)", "BMI = 70 / (1.75 × 1.75) = 70 / 3.0625 = 22.86 kg/m² (නිරෝගී බර)."),
        q("සිරුරේ බර 80 kg සහ උස 1.75 m වූ පුද්ගලයෙකුගේ BMI අගය නිවැරදිව ගණනය කළ විට ලැබෙන්නේ කුමක්ද?", "26.12 kg/m² (වැඩි බර)", "20.5 kg/m² (නිරෝගී)", "16.0 kg/m² (අඩු බර)", "32.5 kg/m² (ස්ථූල)", "BMI = 80 / 3.0625 = 26.12 kg/m² (වැඩි බර)."),
        q("සිරුරේ බර 95 kg සහ උස 1.75 m වූ අයෙකුගේ BMI අගය අනුව ඔහු අයත් වන කාණ්ඩය කුමක්ද?", "31.02 kg/m² (ස්ථූලතාව)", "24.0 kg/m² (නිරෝගී)", "19.0 kg/m² (අඩු බර)", "27.5 kg/m² (වැඩි බර)", "BMI = 95 / 3.0625 = 31.02 kg/m² වන බැවින් ස්ථූලතා කාණ්ඩයට වැටේ."),
        q("සිරුරේ බර 52 kg සහ උස 1.65 m වූ අයෙකුගේ BMI අගය නිවැරදිව ගණනය කළ විට ලැබෙන්නේ කුමක්ද?", "19.10 kg/m² (නිරෝගී බර)", "15.0 kg/m² (අඩු බර)", "26.0 kg/m² (වැඩි බර)", "30.0 kg/m² (ස්ථූල)", "BMI = 52 / (1.65 × 1.65) = 52 / 2.7225 = 19.10 kg/m² (නිරෝගී බර)."),
        q("සිරුරේ බර 68 kg සහ උස 1.65 m වූ අයෙකුගේ BMI අගය හා ශරීර තත්ත්වය කුමක්ද?", "24.98 kg/m² (නිරෝගී බරෙහි උපරිම සීමාව)", "18.0 kg/m² (අඩු බර)", "28.5 kg/m² (වැඩි බර)", "34.0 kg/m² (ස්ථූල)", "BMI = 68 / 2.7225 = 24.98 kg/m² (නිරෝගී බර පරාසයේ ඉහළ සීමාව)."),
        q("සිරුරේ බර 75 kg සහ උස 1.65 m වූ පුද්ගලයෙකුගේ BMI අගය අනුව ඔහු අයත් වන කාණ්ඩය කුමක්ද?", "27.55 kg/m² (වැඩි බර)", "21.0 kg/m² (නිරෝගී)", "16.5 kg/m² (අඩු බර)", "32.0 kg/m² (ස්ථූල)", "BMI = 75 / 2.7225 = 27.55 kg/m² (වැඩි බර)."),
        q("සිරුරේ බර 60 kg සහ උස 1.8 m වූ උස පුද්ගලයෙකුගේ BMI අගය කුමක්ද?", "18.52 kg/m² (නිරෝගී බරෙහි අවම සීමාව)", "24.0 kg/m² (නිරෝගී)", "14.5 kg/m² (අඩු බර)", "28.0 kg/m² (වැඩි බර)", "BMI = 60 / (1.8 × 1.8) = 60 / 3.24 = 18.52 kg/m² වේ."),
        q("සිරුරේ බර 55 kg සහ උස 1.8 m වූ අයෙකුගේ BMI අගය අනුව ඔහුගේ සෞඛ්‍ය තත්ත්වය කුමක්ද?", "16.98 kg/m² (අඩු බර තත්ත්වය)", "22.0 kg/m² (නිරෝගී)", "26.5 kg/m² (වැඩි බර)", "31.0 kg/m² (ස්ථූල)", "BMI = 55 / 3.24 = 16.98 kg/m² බැවින් අඩු බර කාණ්ඩයට අයත් වේ."),
        q("සිරුරේ බර 75 kg සහ උස 1.8 m වූ පුද්ගලයෙකුගේ BMI අගය නිවැරදිව ගණනය කළ විට ලැබෙන්නේ කුමක්ද?", "23.15 kg/m² (නිරෝගී බර)", "17.0 kg/m² (අඩු බර)", "28.0 kg/m² (වැඩි බර)", "33.0 kg/m² (ස්ථූල)", "BMI = 75 / 3.24 = 23.15 kg/m² (නිරෝගී බර)."),
        q("සිරුරේ බර 85 kg සහ උස 1.8 m වූ පුද්ගලයෙකුගේ BMI අගය අනුව ඔහු අයත් වන්නේ කුමන කාණ්ඩයටද?", "26.23 kg/m² (වැඩි බර)", "20.5 kg/m² (නිරෝගී)", "16.0 kg/m² (අඩු බර)", "32.0 kg/m² (ස්ථූල)", "BMI = 85 / 3.24 = 26.23 kg/m² (වැඩි බර)."),
        q("සිරුරේ බර 100 kg සහ උස 1.8 m වූ අයෙකුගේ BMI අගය හා තත්ත්වය කුමක්ද?", "30.86 kg/m² (ස්ථූලතාව)", "24.0 kg/m² (නිරෝගී)", "19.5 kg/m² (අඩු බර)", "27.0 kg/m² (වැඩි බර)", "BMI = 100 / 3.24 = 30.86 kg/m² (ස්ථූලතා කාණ්ඩය)."),
        q("පිරිමි පුද්ගලයෙකුගේ ඉණ වටප්‍රමාණය 90 cm සහ උකුල වටප්‍රමාණය 100 cm නම් ඔහුගේ WHR අගය කුමක්ද?", "0.90 (අවදානම් සීමාව)", "1.10", "0.75", "0.50", "WHR = 90 / 100 = 0.90 වේ."),
        q("කාන්තාවකගේ ඉණ වටප්‍රමාණය 72 cm සහ උකුල වටප්‍රමාණය 90 cm නම් ඇයගේ WHR අගය කොපමණද?", "0.80 (නිරෝගී පරාසය)", "1.25", "0.95", "0.60", "WHR = 72 / 90 = 0.80 වන අතර එය 0.85 ට අඩු නිරෝගී අගයකි."),
        q("පිරිමි පුද්ගලයෙකුගේ ඉණ වටප්‍රමාණය 95 cm සහ උකුල වටප්‍රමාණය 100 cm නම් ඔහුගේ WHR අගය හා අවදානම කුමක්ද?", "0.95 (හෘද රෝග අවදානම ඉහළයි)", "0.80 (අවදානමක් නැත)", "1.20", "0.65", "WHR = 95 / 100 = 0.95 වන අතර පිරිමින්ගේ 0.90 සීමාව ඉක්මවා ඇත."),
        q("කාන්තාවකගේ ඉණ වටප්‍රමාණය 81 cm සහ උකුල වටප්‍රමාණය 90 cm නම් ඇයගේ WHR අගය අනුව සෞඛ්‍ය තත්ත්වය කුමක්ද?", "0.90 (පරිවෘත්තීය රෝග අවදානම ඉහළයි)", "0.75 (නිරෝගී)", "1.11", "0.55", "WHR = 81 / 90 = 0.90 වන අතර කාන්තාවන්ගේ 0.85 සීමාව ඉක්මවා ඇත."),
        q("පාසල් සිසුවෙකු දිනපතා දත් මදින විට 'දන්තාලේපන' භාවිත කිරීමේදී ගත යුතු ප්‍රශස්ථ ප්‍රමාණය කුමක්ද?", "කඩල ඇටයක තරම් කුඩා ප්‍රමාණයක් (Pea-sized amount)", "දන්ත බුරුසුව පුරාම පිරෙන සේ විශාල ප්‍රමාණයක්", "හැන්දක් පමණ ප්‍රමාණයක්", "දන්තාලේපන භාවිතය අනවශ්‍යය", "කඩල ඇටයක තරම් ප්‍රමාණයක් නිසි පරිදි දත් මතුපිට පිරිසිදු කිරීමට හා ෆ්ලෝරයිඩ් සැපයීමට ප්‍රමාණවත්ය."),
        q("දත් බුරුසුවකින් දත් මදින විට විදුරුමසට හානි නොවී දන්ත ඵලකය ඉවත් කිරීමට සුදුසු බුරුසු චලනය කුමක්ද?", "විදුරුමසේ සිට දතෙහි අග දෙසට මෘදු ලෙස අතුල්ලා පිසදැමීම", "දත් හරහා තිරස් අතට තදින් ඇතිල්ලීම", "ඉතා තදින් දත් මත පීඩනය යෙදීම", "එක් ස්ථානයක පමණක් බුරුසුව තබා සිටීම", "විදුරුමසේ සිට ඉහළට හෝ පහළට මෘදු වක්‍රාකාර චලනයන් මගින් එනමලය හා විදුරුමස ආරක්ෂා වේ."),
        q("මුඛයේ සාමාන්‍ය pH අගය 5.5 ට වඩා අඩුවීම මගින් දත්වලට සිදුවන සෘජු හානිය කුමක්ද?", "දන්ත එනමලය දියවී විඛාදනය වීම ඇරඹීම (Demineralization)", "දත් ශක්තිමත් වීම", "දත්වල කැල්සියම් වැඩිවීම", "විදුරුමස ඝනකම් වීම", "ආම්ලික පරිසරයකදී (pH < 5.5) එනමලයේ ඇති කැල්සියම් හා පොස්පේට් දියවී කුහර ඇතිවේ."),
        q("දන්ත ක්ෂයවීම වළක්වා ගැනීමට ආහාර ගැනීමෙන් පසු මුඛය පිරිසිදු ජලයෙන් හොඳින් සේදීම වැදගත් වන්නේ ඇයි?", "මුඛයේ රැඳෙන ආහාර කැබලි ඉවත් වී අම්ල නිපදවීම අවම වන බැවිනි", "දත් ගැලවී යාමට", "මුඛයේ උෂ්ණත්වය ඉහළ නැංවීමට", "කෙළ නිෂ්පාදනය නැවැත්වීමට", "ආහාර ගත් වහාම වතුරෙන් මුඛය සේදීමෙන් බැක්ටීරියාවලට ලැබෙන සීනි ප්‍රමාණය අඩු වේ."),
        q("අක්ෂි ආරක්ෂාව සඳහා 'අවිදුර දෘෂ්ටිකතාව' (Myopia) ඇති පාසල් ළමුන් පැළඳිය යුතු කාච වර්ගය කුමක්ද?", "අවතල කාච (Concave lens)", "උත්තල කාච", "සිලින්ඩරාකාර කාච", "ද්විත්ව නාභි කාච", "අවිදුර දෘෂ්ටිකතාවයේදී ඈත ඇති ද්‍රව්‍යවල ප්‍රතිබිම්බය දෘෂ්ටි විතානයට ඉදිරියෙන් වැටෙන බැවින් අවතල කාච යොදයි."),
        q("ළඟ ඇති ද්‍රව්‍ය නොපෙනෙන 'දුර දෘෂ්ටිකතාව' (Hypermetropia) නිවැරදි කර ගැනීමට භාවිත කරන කාච වර්ගය කුමක්ද?", "උත්තල කාච (Convex lens)", "අවතල කාච", "තල කාච", "අඳුරු වීදුරු", "දුර දෘෂ්ටිකතාවයේදී ආලෝක කිරණ නාභිගත වන්නේ දෘෂ්ටි විතානයට පිටුපසින් බැවින් උත්තල කාච භාවිත වේ."),
        q("පාසල් පන්ති කාමරයේ කළු ලෑල්ල නොපෙනී ගොස් ඇස් කුඩා කර බැලීමට සිදුවන සිසුවෙකුට ඇතිවිය හැකි දෘෂ්ටි ආබාධය කුමක්ද?", "අවිදුර දෘෂ්ටිකතාව (Myopia)", "දුර දෘෂ්ටිකතාව", "ඇසේ සුද ඒම", "ග්ලුකෝමා", "දුර ඇති අකුරු බොඳව පෙනීම පාසල් වයසේදී සුලබව හමුවන අවිදුර දෘෂ්ටිකතාවේ මූලික ලක්ෂණයකි."),
        q("නාන තටාකවල පිහිනීමේදී හෝ අපිරිසිදු ජලයේ ස්නානය කිරීමේදී ඇස් ආසාදනවලින් ආරක්ෂා වීමට අනුගමනය කළ හැකි පියවරක් කුමක්ද?", "පිහිනුම් අක්ෂි ආවරණ (Swimming goggles) පැළඳීම", "ඇස් විවෘත කර ජලය යට බැලීම", "ජලයට රසායනික ද්‍රව්‍ය දැමීම", "ස්නානයෙන් පසු ඇස් තදින් ඇතිල්ලීම", "Swimming goggles මගින් ක්ලෝරීන් හා අපිරිසිදු ජල විෂබීජ ඇසෙහි ගැටීම වළක්වයි."),
        q("ශ්‍රවණ ආරක්ෂාව සඳහා අධික ශබ්දයක් සහිත කර්මාන්තශාලා හෝ ගිනි කෙළි පරිශ්‍රයන්හිදී භාවිත කළ යුතු ආරක්ෂක උපාංගය කුමක්ද?", "කර්ණ ආවරණ (Ear muffs / Ear plugs)", "අව් කණ්ණාඩි", "හිස්වැසුම් පමණක්", "මුහුණු ආවරණ", "කර්ණ ආවරණ මගින් ඩෙසිබල් මට්ටම අඩු කර කන් බෙරය හා සංවේදී ශ්‍රවණ සෛල ආරක්ෂා කරයි."),
        q("කනෙහි ඇතිවන ස්වාභාවික 'කන් මැලියම්' (Ear wax) මගින් ශරීරයට සිදුවන ප්‍රයෝජනවත් කාර්යභාරය කුමක්ද?", "දූවිලි, කෘමීන් හා විෂබීජ කන් බෙරයට ඇතුළු වීම වළක්වා කන් නාලය ආරක්ෂා කිරීම", "ශ්‍රවණය සම්පූර්ණයෙන් නැවැත්වීම", "කන ඇතුළත රත් කිරීම", "කන් බෙරය විනාශ කිරීම", "ස්වාභාවික කන් මැලියම්වල ක්ෂුද්‍රජීවී නාශක ගුණ ඇති අතර එය කන ඇතුළත ස්වයංව පිරිසිදු කරයි."),
        q("කනෙන් දියර ගැලීම හෝ දැඩි වේදනාවක් හටගත් විට කිසිසේත්ම නොකළ යුතු නුසුදුසු ක්‍රියාව කුමක්ද?", "විවිධ තෙල් වර්ග, ශාක යුෂ හෝ උල් කූරු කනට දැමීම", "වෛද්‍යවරයෙකු හමුවීම", "පිරිසිදු වියළි රෙදිකඩකින් පිටත පිසදැමීම", "වේදනාව සමනයට විවේක ගැනීම", "නොදන්නා ද්‍රව්‍ය දැමීමෙන් කන් බෙරය සිදුරු වී කන ඇතුළත සැරව ගැලීම උත්සන්න විය හැක."),
        q("සමේ ඇතිවන 'දද' (Eczema) තත්ත්වය පාලනය කර ගැනීමට අනුගමනය කළ හැකි සෞඛ්‍ය උපදෙසක් කුමක්ද?", "සම නිතර මොයිස්චරයිසර් (තෙතමනය රඳවන ආලේපන) මගින් තෙත්ව තබාගැනීම හා කෘත්‍රිම සබන් සීමා කිරීම", "සම අධික ලෙස සීරීම", "උණුසුම් ජලයෙන් නිතර තැවීම", "රළු ඇඳුම් ඇඳීම", "සමේ තෙතමනය ආරක්ෂා කිරීමෙන් කැසීම හා දැවිල්ල පාලනය කරගත හැකිය."),
        q("පාසල් සිසුන් අතර 'හිසේ උකුණන්' (Head lice) බෝවීම වැළැක්වීමට ගත යුතු ප්‍රධාන පියවර කුමක්ද?", "හිසකෙස් පිරිසිදුව තබාගැනීම, පනා හා තුවා හවුලේ භාවිත නොකිරීම හා උකුණු පනාවකින් නිතර පීරීම", "හිසකෙස් කිසිදා නොසේදීම", "අනෙක් අයගේ තොප්පි මාරු කර පැළඳීම", "දිනපතා තෙල් අධිකව ගැල්වීම", "උකුණන් සෘජු ස්පර්ශයෙන් හා හවුලේ භාවිත කරන පනා හා හිස්වැසුම් මගින් බෝවේ."),
        q("නියපොතු වටා ඇති සමෙහි බැක්ටීරියා ආසාදනය වී සැරව පිරීම හඳුන්වන තත්ත්වය කුමක්ද?", "නිය අල මුල පැසවීම (Paronychia)", "හොරි", "අළුහම්", "කුරුලෑ", "නියපොතු සපා කෑම හෝ නියපොතු මුල සම කැඩී යාම නිසා Paronychia බැක්ටීරියා ආසාදනය ඇතිවේ."),
        q("ශාරීරික ඉරියව් නිවැරදිව පවත්වා ගැනීමට නිවසේදී කළ හැකි 'ප්ලෑන්ක්' (Plank) ව්‍යායාමය මගින් ශක්තිමත් වන්නේ කුමන පේශිද?", "උදරය, කොන්ද හා උරහිස් ආශ්‍රිත හර පේශි (Core muscles)", "ඇඟිලි තුඩු පේශි පමණක්", "කන් පේශි", "මුහුණේ පේශි", "Plank ව්‍යායාමය කොඳු ඇට පෙළ කෙළින් තබාගන්නා ගැඹුරු උදර හා කශේරුකා පේශි ශක්තිමත් කරයි."),
        q("නිරෝගී අස්ථි හා දත් වර්ධනය සඳහා කැල්සියම් බහුලව අඩංගු ස්වාභාවික ආහාර ප්‍රභවයක් වන්නේ කුමක්ද?", "කිරි සහ කිරි නිෂ්පාදන, කුඩා මාළු හා තල ඇට", "සුදු පාන්", "පිරිපහදු කළ සීනි", "කාබනේටඩ් බීම", "කටු සමග ආහාරයට ගන්නා හාල්මැස්සන්, කිරි හා තල කැල්සියම්වලින් අනූන ආහාර වේ."),
        q("පාසල් ශිෂ්‍යයෙකුගේ 'ශරීර සනීපාරක්ෂාව' (Body Hygiene) ඉහළ මට්ටමක පැවතීමෙන් ඔහුගේ පෞරුෂයට සිදුවන ධනාත්මක බලපෑම කුමක්ද?", "ආත්ම අභිමානය, ප්‍රබෝධය හා සමාජය සමග සුහදව කටයුතු කිරීමේ හැකියාව ඉහළ යාම", "අන් අය සමග කතා කිරීමෙන් වැළකීම", "නිතර අසනීප වීම", "තනිකම ඇතිවීම", "පිරිසිදුකම පුද්ගලික ආකර්ෂණය හා මනා පෞරුෂයකට පදනම දමයි."),
        q("පාසලක සෞඛ්‍ය ප්‍රවර්ධන වැඩසටහන් සාර්ථක වීම සඳහා සිසුන්ගේ පැත්තෙන් කළ හැකි හොඳම දායකත්වය කුමක්ද?", "සෞඛ්‍ය නීති රීති තමන් පිළිපැදීම, මිතුරන් දැනුවත් කිරීම හා සෞඛ්‍ය සමාජ ක්‍රියාකාරකම්වලට එක්වීම", "වැසිකිළි අපිරිසිදු කිරීම", "කසළ පන්ති කාමරයේ දැමීම", "සෞඛ්‍ය උපදෙස් නොසලකා හැරීම", "ශිෂ්‍ය නායකත්වය හා සහභාගිත්වය පාසල් සෞඛ්‍ය ප්‍රවර්ධනයේ ජීවයයි."),
        q("පරිගණකයක් භාවිත කිරීමේදී වැලමිට, උකුල හා දණහිස් සන්ධි තබාගත යුතු වඩාත්ම සුවපහසු කෝණය කුමක්ද?", "අංශක 90 ක (සෘජු කෝණී) ලිහිල් නැමුමක", "අංශක 180 ක සම්පූර්ණ දිගු කිරීමක", "අංශක 30 ක තද නැමුමක", "ඕනෑම අස්වාභාවික නැමුමක", "සන්ධි අංශක 90 ක කෝණයක තබාගැනීමෙන් කණ්ඩරා හා මාංශපේශී ආතතිය අවම වේ."),
        q("පුටුවක වාඩිවී වැඩ කිරීමේදී පාද දෙකම බිම සමතලාව නොතැබීමෙන් පාදවලට ඇතිවන ගැටලුව කුමක්ද?", "කලවා යට රුධිර වාහිනී තෙරපී පාදවල රුධිර සංසරණය අඩාල වීම හා හිරිවැටීම", "අස්ථි වේගයෙන් දික්වීම", "පාදවල ශක්තිය වැඩිවීම", "නියපොතු ඉක්මනින් වැවීම", "පාද බිම සමතලාව තැබීම හෝ පා ආධාරකයක් (Footrest) භාවිත කිරීම සුදුසුය."),
        q("නින්ද නොයාම (Insomnia) වැළැක්වීම සඳහා රාත්‍රී නින්දට පෙර අනුගමනය කළ යුතු යහපත් චර්යාවක් කුමක්ද?", "නින්දට පැයකට පෙර ඩිජිටල් තිර භාවිතයෙන් වැළකී කාමරය අඳුරු හා නිහඬව තබාගැනීම", "නින්දට පෙර තද කෝපි පානය කිරීම", "ඇඳ මත සිට ත්‍රාසජනක වීඩියෝ නැරඹීම", "අධික තෙල් සහිත බර ආහාර ගැනීම", "නිල් ආලෝකය (Blue light) මගින් මෙලටොනින් නිදි හෝමෝනය නිපදවීම අඩපණ වේ."),
        q("මිනිස් සිරුරේ නිසි සජලනය (Hydration) පවතින්නේදැයි තමන්ටම තහවුරු කරගත හැකි සරලම දෛනික දර්ශකය කුමක්ද?", "පිටවන මුත්‍රා ලා කහ හෝ අවර්ණ පැහැයෙන් පැවතීම", "මුත්‍රා තද දුඹුරු පැහැවීම", "දහඩිය කිසිසේත් නොදැමීම", "දිනකට එක් වරක් පමණක් මුත්‍රා පිටවීම", "තද කහ පැහැති මුත්‍රා ශරීරයේ විජලනය පෙන්නුම් කරන සෘජු සංඥාවකි."),
        q("ක්‍රීඩාවකදී හෝ පන්ති කාමරයේදී ශරීරයේ හදිසි විජලනයක් හඳුනාගත හැකි මූලික රෝග ලක්ෂණ මොනවාද?", "කට සහ තොල් වියළීම, දැඩි පිපාසය, තෙහෙට්ටුව හා කරකැවිල්ල", "අධික ලෙස බඩගිනි දැනීම", "අධික ශක්තියක් ලැබීම", "පෙනීම තියුණු වීම", "මෙම ලක්ෂණ දුටු වහාම ක්‍රියාකාරකම් නවතා සෙවණකට වී ජලය පානය කළ යුතුය."),
        q("නිරෝගී සමක් පවත්වා ගැනීම සඳහා ප්‍රතිඔක්සිකාරකයක් ලෙස ක්‍රියා කරමින් කොලැජන් තන්තු නිපදවීමට උපකාරී වන විටමිනය කුමක්ද?", "විටමින් C", "විටමින් D", "විටමින් K", "විටමින් B12", "විටමින් C මගින් සමේ තුවාල සුවවීම වේගවත් කරන අතර සම රැළි වැටීම පාලනය කරයි."),
        q("පාසල් වියේදී නිවැරදි සෞඛ්‍ය පුරුදු, ඉරියව් හා පෝෂණය ලබාදීම රටක ආර්ථිකයටද ධනාත්මකව බලපාන්නේ ඇයි?", "නිරෝගී, කාර්යක්ෂම හා බෝ නොවන රෝගවලින් තොර ඵලදායී අනාගත ශ්‍රම බලකායක් බිහිවන බැවිනි", "රෝහල් සම්පූර්ණයෙන්ම වසා දැමීමට හැකිවන බැවිනි", "පාසල් පැවැත්වීම නැවැත්වීමට", "රටේ බදු මුදල් අවශ්‍ය නොවන බැවින්", "නිරෝගී දරුවා හෙට දින රටේ ආර්ථික සංවර්ධනයේ මූලික මානව සම්පත බවට පත්වේ."),
        q("දිනපතා නියමිත වේලාවට මලපහ කිරීමේ පුරුද්දක් ඇති කර ගැනීම මගින් වළක්වා ගත හැකි ප්‍රධාන රෝගී තත්ත්වය කුමක්ද?", "මලබද්ධය (Constipation) සහ අර්ශස් රෝගය", "ඇදුම රෝගය", "දියවැඩියාව", "ස්කර්වි", "තන්තු සහිත ආහාර, ප්‍රමාණවත් ජලය හා නිසි පුරුදු මගින් මහාන්ත්‍රයේ සෞඛ්‍යය රැකේ."),
        q("මලපහ කිරීමේ අවශ්‍යතාව දිගු වේලාවක් බලහත්කාරයෙන් මැඩපවත්වාගෙන සිටීමෙන් ඇතිවන අයහපත් ප්‍රතිඵලය කුමක්ද?", "මලපහ වියළී දැඩිවීමෙන් මලබද්ධය හා ගුද මාර්ගයේ පැළීම් ඇතිවීම", "ආහාර දිරවීම වේගවත් වීම", "බඩේ කැක්කුම අඩුවීම", "ප්‍රතිශක්තිය වැඩිවීම", "ස්වාභාවික වේගයන් මැඩපැවැත්වීමෙන් බඩවැල්වල සාමාන්‍ය චලනයන් අඩපණ වේ."),
        q("පාසල් සෞඛ්‍ය පරිසරය තුළ 'ජල මූලාශ්‍ර ආරක්ෂා කිරීම' වැදගත් වන්නේ කුමන කරුණක් උදෙසාද?", "පාචනය, හෙපටයිටිස් A හා උණසන්නිපාතය වැනි ජලයෙන් බෝවන රෝග පැතිරීම වැළැක්වීමට", "පාසලේ විදුලි බිල අඩු කිරීමට", "ක්‍රීඩා පිටියේ තණකොළ වැවීමට පමණක්", "අත් සේදීම නැවැත්වීමට", "පිරිසිදු ක්ලෝරීනීකෘත හෝ උණුකර නිවාගත් ජලය සැපයීම පාසල් දරුවන්ගේ අයිතියකි."),
        q("සිරුරේ බර 62 kg සහ උස 1.55 m වූ පාසල් සිසුවෙකුගේ BMI අගය නිවැරදිව ගණනය කළ විට ලැබෙන්නේ කුමක්ද?", "25.81 kg/m² (වැඩි බර)", "19.0 kg/m² (නිරෝගී)", "15.5 kg/m² (අඩු බර)", "32.0 kg/m² (ස්ථූල)", "BMI = 62 / (1.55 × 1.55) = 62 / 2.4025 = 25.81 kg/m² (වැඩි බර)."),
        q("සිරුරේ බර 50 kg සහ උස 1.55 m වූ අයෙකුගේ BMI අගය නිවැරදිව ගණනය කළ විට ලැබෙන්නේ කුමක්ද?", "20.81 kg/m² (නිරෝගී බර)", "14.5 kg/m² (අඩු බර)", "27.0 kg/m² (වැඩි බර)", "33.5 kg/m² (ස්ථූල)", "BMI = 50 / 2.4025 = 20.81 kg/m² (නිරෝගී බර)."),
        q("සිරුරේ බර 40 kg සහ උස 1.55 m වූ අයෙකුගේ BMI අගය හා තත්ත්වය කුමක්ද?", "16.65 kg/m² (අඩු බර)", "22.0 kg/m² (නිරෝගී)", "26.5 kg/m² (වැඩි බර)", "30.0 kg/m² (ස්ථූල)", "BMI = 40 / 2.4025 = 16.65 kg/m² (අඩු බර කාණ්ඩය)."),
        q("සිරුරේ බර 80 kg සහ උස 1.55 m වූ අයෙකුගේ BMI අගය අනුව ඔහු අයත් වන කාණ්ඩය කුමක්ද?", "33.30 kg/m² (ස්ථූලතාව)", "24.5 kg/m² (නිරෝගී)", "18.0 kg/m² (අඩු බර)", "28.0 kg/m² (වැඩි බර)", "BMI = 80 / 2.4025 = 33.30 kg/m² (ස්ථූලතාව)."),
        q("සිරුරේ බර 56 kg සහ උස 1.6 m වූ පුද්ගලයෙකුගේ BMI අගය නිවැරදිව ගණනය කළ විට ලැබෙන්නේ කුමක්ද?", "21.88 kg/m² (නිරෝගී බර)", "16.0 kg/m² (අඩු බර)", "28.0 kg/m² (වැඩි බර)", "34.0 kg/m² (ස්ථූල)", "BMI = 56 / 2.56 = 21.88 kg/m² (නිරෝගී බර)."),
        q("සිරුරේ බර 44 kg සහ උස 1.6 m වූ අයෙකුගේ BMI අගය හා සෞඛ්‍ය කාණ්ඩය කුමක්ද?", "17.19 kg/m² (අඩු බර)", "23.0 kg/m² (නිරෝගී)", "27.5 kg/m² (වැඩි බර)", "31.0 kg/m² (ස්ථූල)", "BMI = 44 / 2.56 = 17.19 kg/m² (අඩු බර)."),
        q("සිරුරේ බර 78 kg සහ උස 1.6 m වූ අයෙකුගේ BMI අගය අනුව ඔහු අයත් වන කාණ්ඩය කුමක්ද?", "30.47 kg/m² (ස්ථූලතාව)", "22.5 kg/m² (නිරෝගී)", "17.5 kg/m² (අඩු බර)", "26.0 kg/m² (වැඩි බර)", "BMI = 78 / 2.56 = 30.47 kg/m² (ස්ථූලතා කාණ්ඩය)."),
        q("පුද්ගලයෙකුගේ නිරෝගී පැවැත්ම උදෙසා පෞද්ගලික සෞඛ්‍යය, නිවැරදි ඉරියව් හා ශරීර සංවර්ධනය අඛණ්ඩව රැකගැනීමේ අවසාන අරමුණ කුමක්ද?", "දිගුකාලීන නිරෝගී, සතුටුදායක හා ගුණාත්මක ඵලදායී ජීවිතයක් ගත කිරීම", "ධනය පමණක් රැස් කිරීම", "රෝග වැළඳී රෝහල්ගත වීම", "අන් අයගෙන් හුදෙකලා වීම", "කායික, මානසික හා සමාජීය පූර්ණ යහපැවැත්ම ජීවිතයේ සැබෑ සතුට හා ගුණාත්මකභාවය තහවුරු කරයි.")
    )
}

